cat > .copilot-tracking/skraft-plans/pricing/features/pricing-loyalty-discount.feature <<'EOF'
@loyalty-discount
Feature: Loyalty tier discount at checkout
  As a returning customer
  I want my loyalty tier reflected in the checkout total
  So that the price I see rewards my history with the brand

  # SETTLED: every scenario below comes from an approved acceptance criterion (AC-1..AC-4).
  # NOT DECIDED: see the "Not decided" block at the end of this file. Nothing there is executable.

  @happy-path @smoke
  Scenario: Bronze customer is charged the Bronze price on a basket
    Given a returning customer in the Bronze tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9500 cents

  @happy-path
  Scenario: Silver customer is charged the Silver price on a basket
    Given a returning customer in the Silver tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9000 cents

  @happy-path
  Scenario: Gold customer is charged the Gold price on a basket
    Given a returning customer in the Gold tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 8500 cents

  @edge-case
  Scenario: Bronze customer on a tiny basket is charged the whole subtotal
    Given a returning customer in the Bronze tier
    When a basket subtotal of 7 cents is priced
    Then the customer is charged 7 cents

  # NOT DECIDED (no scenario, no test, no expected value on purpose)
  # - Platinum tier: the business has not agreed a reduction (ac-draft "Not decided").
  #   Needed from DISCUSS: one worked example, e.g. "Platinum, 10000 cents -> charged ? cents".
  # - AC-4 wording: the title says the reduction lands "in the customer's favour" but the approved
  #   outcome is 7 cents charged (no reduction on 7 cents). Value is kept verbatim; the rounding
  #   rule behind it is not stated for other subtotals. Needed: one more worked example
  #   (e.g. Bronze, 10 cents) before rounding is generalised.
EOF
cat > tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount/LoyaltyDiscountAcceptanceTests.cs <<'EOF'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public class LoyaltyDiscountAcceptanceTests
{
    [Theory]
    // Bronze customer is charged the Bronze price on a basket
    [InlineData(LoyaltyTier.Bronze, 10000, 9500)]
    public void Returning_customer_is_charged_the_price_of_their_loyalty_tier(
        LoyaltyTier tier, int subtotalCents, int expectedChargedCents)
    {
        var quote = new CalculateLoyaltyDiscount().Handle(
            new CalculateLoyaltyDiscountQuery(subtotalCents, tier));

        Assert.Equal(expectedChargedCents, quote.TotalCents);
    }
}
EOF
